import { expect } from '@esm-bundle/chai';
// DOM nodes are compared as booleans (`a === b`): a failing chai assertion carrying DOM nodes hangs the runner.
// NO static import of the component: <td-copy> is defined LATE (dynamic import below), after the no-JS checks.

// v0.27.0 (ADR 0012, plan v0.27.0-dsuite-p0a §D) — td_copy() / <td-copy> hydrate in place, contract `copy@1`. Runs in
// Chromium, Firefox AND WebKit (web-test-runner group `engines`). The markup is EXACTLY what php/td.php prints for every case
// of test/ssr/copy.fixtures.json: test/ssr/fixtures/copy.html, generated by `node test/ssr/build-otp-copy-fixture.mjs`
// and kept fresh by test/php/td-ssr-otp-copy.test.js.
const link = document.createElement('link');
link.rel = 'stylesheet';
link.href = '/td.css';
document.head.appendChild(link);
await new Promise((r) => { link.onload = r; link.onerror = r; });

const SPEC = await (await fetch('/test/ssr/copy.fixtures.json')).json();
const FIXTURE = await (await fetch('/test/ssr/fixtures/copy.html')).text();
const TPL = document.createElement('template');
TPL.innerHTML = FIXTURE;

const root = document.createElement('div');
root.innerHTML = FIXTURE;
document.body.appendChild(root);
const hostOf = (id) => root.querySelector(`section[data-case="${id}"] > td-copy`);
const hostHtml = (id) => TPL.content.querySelector(`section[data-case="${id}"] > td-copy`).outerHTML;

// Tampered markup: must render safely and STILL copy the value of the server-authored <code>.
const basic = hostHtml('c-basic');
const MM = {
  'mm-schema': basic.replace('copy@1', 'copy@2'),
  'mm-onclick': basic.replace('<button ', '<button onclick="window.__pwned = 1" '),
  'mm-extra': basic.replace('<span class="td-copy__status"', '<b>thừa</b><span class="td-copy__status"'),
  'mm-label': basic.replace('aria-label="Copy mã khôi phục"', 'aria-label="Khác"'),
  'mm-type': basic.replace('type="button"', 'type="submit"'),
  'mm-no-button': basic.replace(/<button[\s\S]*<\/button>/, ''),
  'mm-plain': '<td-copy label="Tay"><code class="td-copy__source">HAND-1</code></td-copy>',
};
const mismatch = document.createElement('div');
mismatch.innerHTML = Object.entries(MM).map(([id, html]) => html.replace('<td-copy ', `<td-copy id="${id}" `)).join('');
document.body.appendChild(mismatch);

const noJs = {
  code: getComputedStyle(hostOf('c-basic').querySelector('code')).display,
  button: getComputedStyle(hostOf('c-basic').querySelector('button')).display,
};
const buttons = {};
for (const c of SPEC.cases) buttons[c.id] = hostOf(c.id).querySelector('button');

await import('./td-copy.js');

const wait = (ms) => new Promise((r) => setTimeout(r, ms));
function fakeClipboard() {
  const written = [];
  Object.defineProperty(navigator, 'clipboard', { value: { writeText: (t) => { written.push(t); return Promise.resolve(); } }, configurable: true });
  return written;
}

describe('td-copy SSR (copy@1) — no JS', () => {
  it('the source <code> shows, the icon button is hidden', () => {
    expect(noJs.code).to.not.equal('none');
    expect(noJs.button).to.equal('none');
  });
});

describe('td-copy SSR (copy@1) — adopted in place', () => {
  for (const c of SPEC.cases) {
    it(`${c.id}: same button node, marker consumed, copies the server value`, async () => {
      const host = hostOf(c.id);
      const btn = host.querySelector('button.td-copy');
      expect(btn === buttons[c.id], 'button node kept').to.equal(true);
      expect(host.hasAttribute('data-td-ssr')).to.equal(false);
      expect(btn.getAttribute('aria-label')).to.equal(c.expect.label);
      expect(btn.classList.contains(`td-copy--${c.expect.size}`)).to.equal(true);
      expect(getComputedStyle(host.querySelector('code.td-copy__source')).display).to.equal('none');
      expect(getComputedStyle(btn).display).to.not.equal('none');
      for (const bad of c.dropOnHost || []) expect(host.hasAttribute(bad), bad).to.equal(false);
      const written = fakeClipboard();
      const details = [];
      host.addEventListener('copy-success', (e) => details.push(e.detail), { once: true });
      btn.click();
      await wait(20);
      expect(written).to.deep.equal([c.expect.value]);
      expect('value' in details[0]).to.equal(!c.expect.sensitive);
    });
  }
});

describe('td-copy SSR — refused markup renders safely, the captured source still copies', () => {
  for (const id of Object.keys(MM)) {
    it(`${id}: re-rendered, nothing foreign, copies the original value`, async () => {
      const host = mismatch.querySelector(`#${id}`);
      expect(host.hasAttribute('data-td-ssr')).to.equal(false);
      expect(host.querySelectorAll('button').length).to.equal(1);
      expect(!!host.querySelector('[onclick], b, button[type="submit"]')).to.equal(false);
      expect(host.querySelectorAll('code.td-copy__source').length).to.equal(1);
      const written = fakeClipboard();
      host.querySelector('button').click();
      await wait(20);
      expect(written).to.deep.equal([id === 'mm-plain' ? 'HAND-1' : 'ABCD-1234-EFGH']);
      expect(window.__pwned).to.equal(undefined);
    });
  }
});
